@router.get("/api/v1/expenses/{expense_id}/audit-context")
def get_expense_audit_context(
    expense_id: int,
    session: Session = Depends(get_session),
    current_user: User = Depends(get_current_user)
):
    stmt = (
        select(ExpenseReport)
        .join(ExpenseReport.project)
        .join(Project.department)
        .where(
            ExpenseReport.id == expense_id,
            Department.organization_id == current_user.organization_id,
            Project.members.any(User.id == current_user.id)
        )
    )
    expense = session.exec(stmt).first()
    if not expense:
        raise HTTPException(status_code=404, detail="Expense report not found or unauthorized")
    return {
        "expense_id": expense.id,
        "amount": expense.amount,
        "project_name": expense.project.name,
        "department_budget": expense.project.department.total_budget,
        "ledger_account": expense.project.department.internal_ledger_code
    }
